// ---- 1440 array parser + deterministic filter + picker (with revisit fallback) ----
// Dedup is on company name only -- once a company is briefed it stays quiet for
// 30 days regardless of what news comes out. Prevents same-company-different-trigger repeats.
const response = $input.first().json;
const textBlocks = (response.content || []).filter(c => c.type === 'text');
if (textBlocks.length === 0) {
  throw new Error('Run Signals returned no text content. Raw: ' + JSON.stringify(response).slice(0, 500));
}
let raw = textBlocks.map(b => b.text).join('\n').trim();
raw = raw.replace(/\x60\x60\x60json\s*/gi, '').replace(/\x60\x60\x60\s*/g, '').trim();
const firstBracket = raw.indexOf('[');
const lastBracket = raw.lastIndexOf(']');
if (firstBracket === -1 || lastBracket === -1 || lastBracket <= firstBracket) {
  throw new Error('No JSON array found in Run Signals output. Likely truncated - raise max_tokens. Raw: ' + raw.slice(0, 800));
}
let candidates;
try {
  candidates = JSON.parse(raw.substring(firstBracket, lastBracket + 1));
} catch (e) {
  throw new Error('Run Signals array failed to parse. Raw: ' + raw.slice(0, 800));
}
if (!Array.isArray(candidates) || candidates.length === 0) {
  throw new Error('Parsed value is not a non-empty array. Raw: ' + raw.slice(0, 800));
}

// HARD BLOCK = 1440 active deals + permanent suppressions. Never sent, period.
const HARD_BLOCK = [
  'Factory AI', 'JFrog', 'Mistral AI', 'Luminary Cloud', 'Netomi',
  'Shield AI', 'Wayve', 'Lattice', 'Omni Analytics', 'Legora',
  'Cerebras Systems', 'Sierra'
];

function normalise(name) {
  return (name || '').toLowerCase()
    .replace(/\b(inc|ltd|llc|corp|technologies|technology|ai|the)\b/g, '')
    .replace(/[^a-z0-9]/g, '').trim();
}
function isBlocked(companyNorm, listNorm) {
  return listNorm.some(function (b) {
    return b.length > 0 && (companyNorm === b ||
      companyNorm.indexOf(b) !== -1 || b.indexOf(companyNorm) !== -1);
  });
}

const staticData = $getWorkflowStaticData('global');
if (!staticData.surfaced) staticData.surfaced = [];
// For ONE clean test, temporarily uncomment, run once, then re-comment:
// staticData.surfaced = [];
const COOLING_DAYS = 30;
const now = Date.now();
staticData.surfaced = staticData.surfaced.filter(function (s) {
  return (now - s.ts) / 86400000 < COOLING_DAYS;
});
const hardBlockNorm = HARD_BLOCK.map(normalise);

const scanned = [];
let winner = null;
let revisitCandidate = null;

for (const c of candidates) {
  const nameNorm = normalise(c.company);
  const trigger = ((c.trigger_reason || (c.key_facts && c.key_facts.trigger) || '') + '').toLowerCase().trim();
  const hard = isBlocked(nameNorm, hardBlockNorm);
  // Dedup on company name only.
  const cooling = staticData.surfaced.some(function (s) { return s.name === nameNorm; });
  let status = 'eligible';
  if (hard) status = 'hard_blocked';
  else if (cooling) status = 'dedup_cooling';
  scanned.push({ company: c.company, score: c.score, status: status });
  if (status === 'eligible' && !winner) winner = c;
  if (!hard && !revisitCandidate) revisitCandidate = c;
}

let revisitFlag = false;
if (!winner) {
  // All candidates were duplicates or hard-blocked. Send the strongest non-active-deal
  // candidate as a revisit, accepting a re-surface when nothing fresher qualifies.
  winner = revisitCandidate || candidates[0];
  revisitFlag = true;
}

const winnerNorm = normalise(winner.company);
const winnerTrig = ((winner.trigger_reason || (winner.key_facts && winner.key_facts.trigger) || '') + '').toLowerCase().trim();
// Dedup on company name only.
const existingIdx = staticData.surfaced.findIndex(function (s) { return s.name === winnerNorm; });
if (existingIdx >= 0) staticData.surfaced[existingIdx].ts = now;
else staticData.surfaced.push({ name: winnerNorm, trigger: winnerTrig, display: winner.company, ts: now });

// Auto-increment brief number, persisted in static data across runs.
// Seeded at 9 so the first scheduled run increments to 010, matching the
// last manually-set brief number. Subsequent runs increment by 1.
if (typeof staticData.lastBriefNumber !== 'number') staticData.lastBriefNumber = 9;
staticData.lastBriefNumber += 1;
winner.brief_number = String(staticData.lastBriefNumber).padStart(3, '0');

winner._revisit = revisitFlag;
winner.scanned = scanned;
return [{ json: winner }];

const sd = $getWorkflowStaticData('global');
sd._loop = { attempts: 0, rejects: [] };
return $input.all();

const sd = $getWorkflowStaticData('global');
if (!sd._loop) sd._loop = { attempts: 0, rejects: [] };
sd._loop.attempts += 1;
const scanned = ($input.first().json.scanned) || [];
for (const s of scanned) {
  if (s && s.company && sd._loop.rejects.indexOf(s.company) === -1) {
    sd._loop.rejects.push(s.company);
  }
}
const MAX_ATTEMPTS = 3;
const attempts = sd._loop.attempts;
return [{ json: {
  attempts: attempts,
  retry: attempts < MAX_ATTEMPTS,
  rejectedThisRun: sd._loop.rejects.join(', ') || 'none'
} }];
